<script setup>
import { nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";
const props=defineProps({ open:Boolean, chapters:{ type:Array, default:()=>[] }, current:Number }); const emit=defineEmits(["close","select"]); const panel=ref();
function onKey(event){ if(!props.open) return; if(event.key==="Escape") emit("close"); if(event.key!=="Tab") return; const nodes=[...panel.value.querySelectorAll("button")]; if(!nodes.length)return; const first=nodes[0],last=nodes.at(-1); if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
watch(()=>props.open, async(value)=>{ document.body.classList.toggle("drawer-open",value); if(value){await nextTick();panel.value?.querySelector("button")?.focus();} });
onMounted(()=>document.addEventListener("keydown",onKey)); onBeforeUnmount(()=>{document.removeEventListener("keydown",onKey);document.body.classList.remove("drawer-open");});
</script>
<template><Teleport to="body"><div v-if="open" class="drawer-backdrop" @click.self="emit('close')"><section ref="panel" class="chapter-drawer" role="dialog" aria-modal="true" aria-labelledby="contents-title"><header><h2 id="contents-title">Contents</h2><button class="icon-button" aria-label="Close contents" @click="emit('close')"><i class="fa-solid fa-xmark" /></button></header><div class="chapter-options"><button v-for="chapter in chapters" :key="chapter.id" :class="{ current:chapter.chapter_number===current }" @click="emit('select',chapter.chapter_number)"><span>{{ chapter.chapter_number }}</span><small>{{ chapter.title }}</small><i v-if="chapter.chapter_number===current" class="fa-solid fa-book-open" aria-hidden="true" /></button></div></section></div></Teleport></template>
